Standard exercism Python solution:

```python
class Board:
    """Count territories of each player in a Go game"""

    def __init__(self, board):
        self.board = board

    def territory(self, x, y):
        if not (0 <= x < len(self.board[0]) and 0 <= y < len(self.board)):
            raise ValueError("Invalid coordinate")

        if self.board[y][x] != " ":
            return (NONE, set())

        territory = set()
        frontier = {(x, y)}
        while frontier:
            cx, cy = frontier.pop()
            if (cx, cy) in territory:
                continue
            territory.add((cx, cy))
            for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nx, ny = cx + dx, cy + dy
                if 0 <= nx < len(self.board[0]) and 0 <= ny < len(self.board):
                    if self.board[ny][nx] == " " and (nx, ny) not in territory:
                        frontier.add((nx, ny))

        # determine the owner: the set of colors of adjacent stones
        colors = set()
        for (cx, cy) in territory:
            for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nx, ny = cx + dx, cy + dy
                if 0 <= nx < len(self.board[0]) and 0 <= ny < len(self.board):
                    if self.board[ny][nx] in (WHITE, BLACK):
                        colors.add(self.board[ny][nx])

        if len(colors) == 1:
            owner = colors.pop()
        else:
            owner = NONE

        return (owner, territory)

    def territories(self):
        territories = {WHITE: set(), BLACK: set(), NONE: set()}
        for y, row in enumerate(self.board):
            for x, cell in enumerate(row):
                if cell == " ":
                    owner, territory = self.territory(x, y)
                    territories[owner] |= territory
        return territories
```

Note: when the board is empty, `self.board[0]` will fail. In test_one_territory_is_the_whole_board, board = [" "] — no problem. But for safety, handle an empty board: width = len(self.board[0]) if self.board else 0.

Constants: WHITE = "W", BLACK = "B", NONE = "".

